import {subnet,addr,envelope,validate} from './network.js';
export const uid=()=>Array.from(crypto.getRandomValues(new Uint8Array(16)),b=>b.toString(16).padStart(2,'0')).join('');
export const blankPlan=()=>({version:2,name:'My network plan',roots:[{id:uid(),name:'Root address space',cidr:'192.168.0.0/16',status:'container',children:[]}]});
export function structure(plan){
 if(plan?.version!==2||typeof plan.name!=='string'||!Array.isArray(plan.roots)||!plan.roots.length)throw Error('Expected version 2, name and at least one root.');
 let count=0,ids=new Set();
 function walk(nodes,depth){if(depth>33)throw Error('Maximum nesting is 33 levels.');for(const n of nodes){if(++count>2000)throw Error('Maximum 2,000 spaces.');if(typeof n.id!=='string'||!n.id||ids.has(n.id))throw Error('Space IDs must be unique.');ids.add(n.id);if(typeof n.name!=='string'||!['container','active','reserved'].includes(n.status)||!Array.isArray(n.children))throw Error('Each space needs name, status and children.');subnet(n.cidr);if(n.requiredHosts!==undefined&&(!Number.isInteger(n.requiredHosts)||n.requiredHosts<0))throw Error('Host demand must be a non-negative integer.');walk(n.children,depth+1)}}walk(plan.roots,0);return plan;
}
export function migrate(p){
 if(p.version===2)return structure(structuredClone(p));
 const errors=validate(p);if(errors.length)throw Error(errors.join('; '));
 const pools=p.pools.map(pool=>({...pool,status:'container',children:pool.allocations.map(a=>{let n={...a,children:[]};delete n.growthPrefix;if(a.growthPrefix===undefined)return n;const e=envelope(a),s=subnet(a.cidr);return {id:a.id+'-envelope',name:a.name+' · growth envelope',cidr:e.cidr,status:'container',children:[n,{id:a.id+'-reserve',name:'Growth for '+a.name,cidr:addr(s.end+1)+'/'+s.p,status:'reserved',children:[],reservationFor:a.id}]}})}));pools.forEach(p=>delete p.allocations);
 const roots=p.campus?[{id:'campus-container',name:p.campus.name,cidr:p.campus.cidr,status:'container',children:pools.filter(x=>p.campus.poolIds.includes(x.id))},...pools.filter(x=>!p.campus.poolIds.includes(x.id))]:pools;
 return structure({version:2,name:p.name,description:p.description||'',sourceNotes:p.sourceNotes||[],roots});
}
export function locate(p,id){let found;function walk(nodes,parent=null){for(const n of nodes){if(n.id===id)found={node:n,parent,siblings:nodes};walk(n.children,n)}}walk(p.roots);return found}
export function diagnostics(p){const issues=[];function walk(nodes,parent){for(const n of nodes){let s=subnet(n.cidr);if(!s.aligned)issues.push({id:n.id,message:`${n.name}: address is not aligned; network is ${s.cidr}.`});if(parent){let r=subnet(parent.cidr);if(s.start<r.start||s.end>r.end)issues.push({id:n.id,message:`${n.name} is outside ${parent.name}.`});if(s.p<=r.p)issues.push({id:n.id,message:`${n.name} must be a smaller block than its parent.`})}if(n.children.length&&n.status!=='container')issues.push({id:n.id,message:`${n.name}: a space with children must be a container, not an active LAN/reservation.`});if(n.requiredHosts>s.usable)issues.push({id:n.id,message:`${n.name}: host demand exceeds ${s.usable} usable addresses.`});walk(n.children,n)}for(let i=0;i<nodes.length;i++)for(let j=i+1;j<nodes.length;j++){let a=subnet(nodes[i].cidr),b=subnet(nodes[j].cidr),start=Math.max(a.start,b.start),end=Math.min(a.end,b.end);if(start<=end)issues.push({id:nodes[i].id,other:nodes[j].id,start,end,message:`${nodes[i].name} overlaps ${nodes[j].name}: ${addr(start)} – ${addr(end)} (${end-start+1} addresses).`})}}walk(p.roots);return issues}
export function gaps(parent){let r=subnet(parent.cidr),ranges=parent.children.map(n=>subnet(n.cidr)).filter(n=>n.end>=r.start&&n.start<=r.end).sort((a,b)=>a.start-b.start),cursor=r.start,out=[];for(let n of ranges){let start=Math.max(r.start,n.start),end=Math.min(r.end,n.end);if(start>cursor)out.push({start:cursor,end:start-1});cursor=Math.max(cursor,end+1)}if(cursor<=r.end)out.push({start:cursor,end:r.end});return out}
export function nextFree(parent,prefix){const size=2**(32-prefix);if(prefix<=subnet(parent.cidr).p||prefix>32)return null;for(let g of gaps(parent)){let start=Math.ceil(g.start/size)*size;if(start+size-1<=g.end)return addr(start)+'/'+prefix}return null}
export function split(node){let n=subnet(node.cidr);if(!n.aligned||n.p===32||node.children.length)throw Error('Split requires an aligned, empty block larger than /32.');node.status='container';delete node.requiredHosts;node.children=[0,1].map(i=>({id:uid(),name:node.name+' · '+(i?'upper':'lower')+' half',cidr:addr(n.start+i*n.size/2)+'/'+(n.p+1),status:'active',children:[]}));}
